-- Idempotent seed data: sample products, customers, and orders (with order_items)
-- for local/dev/QA environments — NOT for production use.
-- Safe to re-run: every row uses a fixed, deterministic id and ON CONFLICT DO NOTHING.
--
-- Order status values: 1=Draft, 2=Submitted, 3=Paid, 4=Cancelled
--
-- Run against the `arkcloud` database after migrations have been applied:
--   psql "Host=localhost;Port=5432;Database=arkcloud;Username=arkcloud;Password=arkcloud" -f seed_catalog_and_orders.sql
-- Run seed_users.sql first (or independently, they don't overlap).

BEGIN;

ON CONFLICT ("Id") DO NOTHING;

ON CONFLICT ("Id") DO NOTHING;

ON CONFLICT ("Id") DO NOTHING;

ON CONFLICT ("Id") DO NOTHING;

COMMIT;
